package com.boostdecay;

import com.boostdecay.render.SplatStyle;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BoostDecayConfig.GROUP)
public interface BoostDecayConfig extends Config
{
	String GROUP = "boostdecayhitsplats";

	@ConfigItem(
		keyName = "showNumber",
		name = "Show number",
		description = "Draw the number on the splat",
		position = 0
	)
	default boolean showNumber()
	{
		return true;
	}

	@Range(min = 300, max = 3000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "durationMillis",
		name = "Duration",
		description = "How long each splat stays on screen",
		position = 1
	)
	default int durationMillis()
	{
		return 1200;
	}

	@Range(min = -100, max = 100)
	@ConfigItem(
		keyName = "verticalOffset",
		name = "Vertical offset",
		description = "Extra height above the default position, in local units",
		position = 2
	)
	default int verticalOffset()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "preview",
		name = "Preview",
		description = "Keep showing sample splats on your character so you can try out the look",
		position = 3
	)
	default boolean preview()
	{
		return false;
	}

	@ConfigSection(
		name = "Hitpoints",
		description = "Splats for overheal Hitpoints decay",
		position = 10
	)
	String hitpointsSection = "hitpoints";

	@ConfigItem(
		keyName = "hitpointsEnabled",
		name = "Enabled",
		description = "Show splats for overheal Hitpoints decay",
		section = hitpointsSection,
		position = 11
	)
	default boolean hitpointsEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hitpointsStyle",
		name = "Style",
		description = "Use the Hitpoints skill icon or a drawn circle",
		section = hitpointsSection,
		position = 12
	)
	default SplatStyle hitpointsStyle()
	{
		return SplatStyle.ICON;
	}

	@ConfigItem(
		keyName = "hitpointsColor",
		name = "Color",
		description = "Fill color when the style is Drawn",
		section = hitpointsSection,
		position = 13
	)
	default Color hitpointsColor()
	{
		return new Color(0x8E44AD);
	}
}

package com.boostdecay;

import com.boostdecay.core.BoostDecayTracker;
import com.boostdecay.core.DecayEvent;
import com.boostdecay.core.HitpointsDecayRule;
import com.boostdecay.core.StatDecayRule;
import com.boostdecay.core.StatSnapshot;
import com.boostdecay.core.TickContext;
import com.boostdecay.render.BoostDecayOverlay;
import com.boostdecay.render.SplatAppearance;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Boost Decay Hitsplats",
	description = "Shows a hitsplat each time overheal Hitpoints decay",
	tags = {"hitpoints", "hp", "overheal", "anglerfish", "brew", "hitsplat", "boost"}
)
public class BoostDecayPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BoostDecayConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BoostDecayOverlay overlay;

	@Inject
	private SplatAppearance appearance;

	private final BoostDecayTracker tracker = new BoostDecayTracker(Collections.emptyList());

	private boolean hitsplatOnLocalPlayer;

	@Override
	protected void startUp()
	{
		appearance.rebuild();
		tracker.setRules(buildRules());
		tracker.reset();
		hitsplatOnLocalPlayer = false;
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.clear();
		tracker.reset();
	}

	private List<StatDecayRule> buildRules()
	{
		List<StatDecayRule> rules = new ArrayList<>();
		if (config.hitpointsEnabled())
		{
			rules.add(new HitpointsDecayRule());
		}
		return rules;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			hitsplatOnLocalPlayer = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			tracker.reset();
			hitsplatOnLocalPlayer = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Map<Skill, StatSnapshot> snapshots = new EnumMap<>(Skill.class);
		for (Skill skill : tracker.getSkills())
		{
			snapshots.put(skill, new StatSnapshot(client.getBoostedSkillLevel(skill), client.getRealSkillLevel(skill)));
		}

		TickContext ctx = new TickContext(hitsplatOnLocalPlayer, System.currentTimeMillis());
		hitsplatOnLocalPlayer = false;

		List<DecayEvent> events = tracker.onTick(snapshots, ctx);
		if (!events.isEmpty())
		{
			log.debug("Decay events: {}", events);
			overlay.add(events);
		}

		if (config.preview())
		{
			addPreviewEvents(ctx.getNowMillis());
		}
	}

	/**
	 * Shows a sample splat for each skill with an appearance, starting a new one as soon
	 * as the previous one has finished, so look and duration changes show up right away.
	 */
	private void addPreviewEvents(long nowMillis)
	{
		List<DecayEvent> preview = new ArrayList<>();
		for (Skill skill : appearance.getSkills())
		{
			if (!overlay.isShowing(skill, nowMillis))
			{
				preview.add(new DecayEvent(skill, -1, nowMillis));
			}
		}
		overlay.add(preview);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BoostDecayConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		clientThread.invoke(() ->
		{
			tracker.setRules(buildRules());
			appearance.rebuild();
		});
	}

	@Provides
	BoostDecayConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BoostDecayConfig.class);
	}
}

package com.boostdecay.core;

import net.runelite.api.Skill;

/**
 * The decay test shared by every boosted stat: the stat was above its real level,
 * dropped by exactly 1, and its real level did not change.
 */
public class BoostDecayRule implements StatDecayRule
{
	private final Skill skill;

	public BoostDecayRule(Skill skill)
	{
		this.skill = skill;
	}

	@Override
	public Skill skill()
	{
		return skill;
	}

	@Override
	public boolean isDecay(StatSnapshot prev, StatSnapshot now, TickContext ctx)
	{
		return now.getReal() == prev.getReal()
			&& prev.getBoosted() > prev.getReal()
			&& now.getBoosted() == prev.getBoosted() - 1;
	}
}

package com.boostdecay.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;

/**
 * Remembers the previous snapshot of each registered skill and turns each tick's
 * snapshots into decay events using the registered rules.
 */
public class BoostDecayTracker
{
	private final Map<Skill, StatDecayRule> rules = new EnumMap<>(Skill.class);
	private final Map<Skill, StatSnapshot> last = new EnumMap<>(Skill.class);

	public BoostDecayTracker(List<StatDecayRule> rules)
	{
		setRules(rules);
	}

	/**
	 * Replaces the registered rules. Skills that stay registered keep their last snapshot.
	 */
	public void setRules(List<StatDecayRule> newRules)
	{
		rules.clear();
		for (StatDecayRule rule : newRules)
		{
			rules.put(rule.skill(), rule);
		}
		last.keySet().retainAll(rules.keySet());
	}

	public Set<Skill> getSkills()
	{
		return Collections.unmodifiableSet(rules.keySet());
	}

	public List<DecayEvent> onTick(Map<Skill, StatSnapshot> snapshots, TickContext ctx)
	{
		List<DecayEvent> events = new ArrayList<>();
		for (StatDecayRule rule : rules.values())
		{
			Skill skill = rule.skill();
			StatSnapshot now = snapshots.get(skill);
			if (now == null)
			{
				continue;
			}

			StatSnapshot prev = last.get(skill);
			if (prev != null && rule.isDecay(prev, now, ctx))
			{
				events.add(new DecayEvent(skill, -1, ctx.getNowMillis()));
			}
			last.put(skill, now);
		}
		return events;
	}

	/**
	 * Forgets all previous snapshots, so the next tick only records state.
	 */
	public void reset()
	{
		last.clear();
	}
}

package com.boostdecay.core;

import lombok.Value;
import net.runelite.api.Skill;

/**
 * One step of a boosted stat moving back toward its real level.
 */
@Value
public class DecayEvent
{
	Skill skill;

	/**
	 * Signed level change. Always -1 in v1; a future restore rule may emit +1.
	 */
	int delta;

	long startMillis;
}

package com.boostdecay.core;

import net.runelite.api.Skill;

/**
 * Hitpoints decay: the shared rule, except any hitsplat on the local player this tick
 * means the drop was damage (or poison, venom, etc.), not decay.
 */
public class HitpointsDecayRule extends BoostDecayRule
{
	public HitpointsDecayRule()
	{
		super(Skill.HITPOINTS);
	}

	@Override
	public boolean isDecay(StatSnapshot prev, StatSnapshot now, TickContext ctx)
	{
		return super.isDecay(prev, now, ctx) && !ctx.isHitsplatOnLocalPlayer();
	}
}

