package com.boostdecay.core;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Skill;
import org.junit.Test;

public class BoostDecayRuleTest
{
	private static final TickContext CTX = new TickContext(false, 0);

	private final BoostDecayRule rule = new BoostDecayRule(Skill.STRENGTH);

	private boolean decay(int prevBoosted, int prevReal, int nowBoosted, int nowReal)
	{
		return rule.isDecay(new StatSnapshot(prevBoosted, prevReal), new StatSnapshot(nowBoosted, nowReal), CTX);
	}

	@Test
	public void dropFromBoostedIsDecay()
	{
		assertTrue(decay(99, 90, 98, 90));
	}

	@Test
	public void finalStepToRealIsDecay()
	{
		assertTrue(decay(91, 90, 90, 90));
	}

	@Test
	public void dropWhenNotBoostedIsNotDecay()
	{
		assertFalse(decay(90, 90, 89, 90));
	}

	@Test
	public void dropOfTwoIsNotDecay()
	{
		assertFalse(decay(99, 90, 97, 90));
	}

	@Test
	public void levelUpIsNotDecay()
	{
		assertFalse(decay(99, 90, 98, 91));
	}

	@Test
	public void restoreOfDrainedStatIsNotDecay()
	{
		assertFalse(decay(80, 90, 81, 90));
	}
}

package com.boostdecay.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

public class BoostDecayTrackerTest
{
	private static final TickContext CTX = new TickContext(false, 1234);

	private static Map<Skill, StatSnapshot> levels(Object... skillBoostedReal)
	{
		Map<Skill, StatSnapshot> map = new EnumMap<>(Skill.class);
		for (int i = 0; i < skillBoostedReal.length; i += 3)
		{
			map.put((Skill) skillBoostedReal[i],
				new StatSnapshot((int) skillBoostedReal[i + 1], (int) skillBoostedReal[i + 2]));
		}
		return map;
	}

	@Test
	public void firstTickAfterConstructionNeverEmits()
	{
		BoostDecayTracker tracker = new BoostDecayTracker(Collections.singletonList(new HitpointsDecayRule()));
		assertTrue(tracker.onTick(levels(Skill.HITPOINTS, 98, 90), CTX).isEmpty());
	}

	@Test
	public void firstTickAfterResetNeverEmits()
	{
		BoostDecayTracker tracker = new BoostDecayTracker(Collections.singletonList(new HitpointsDecayRule()));
		tracker.onTick(levels(Skill.HITPOINTS, 99, 90), CTX);
		tracker.reset();
		assertTrue(tracker.onTick(levels(Skill.HITPOINTS, 98, 90), CTX).isEmpty());
	}

	@Test
	public void emitsDecayEvent()
	{
		BoostDecayTracker tracker = new BoostDecayTracker(Collections.singletonList(new HitpointsDecayRule()));
		tracker.onTick(levels(Skill.HITPOINTS, 99, 90), CTX);
		List<DecayEvent> events = tracker.onTick(levels(Skill.HITPOINTS, 98, 90), CTX);
		assertEquals(Collections.singletonList(new DecayEvent(Skill.HITPOINTS, -1, 1234)), events);
	}

	@Test
	public void twoSkillsEmitIndependentlyOnSameTick()
	{
		BoostDecayTracker tracker = new BoostDecayTracker(Arrays.asList(
			new HitpointsDecayRule(), new BoostDecayRule(Skill.STRENGTH)));
		tracker.onTick(levels(Skill.HITPOINTS, 99, 90, Skill.STRENGTH, 110, 99), CTX);
		List<DecayEvent> events = tracker.onTick(levels(Skill.HITPOINTS, 98, 90, Skill.STRENGTH, 109, 99), CTX);
		// Events come out in Skill enum order
		assertEquals(Arrays.asList(
			new DecayEvent(Skill.STRENGTH, -1, 1234),
			new DecayEvent(Skill.HITPOINTS, -1, 1234)), events);
	}

	@Test
	public void unregisteredSkillNeverEmits()
	{
		BoostDecayTracker tracker = new BoostDecayTracker(Collections.singletonList(new HitpointsDecayRule()));
		tracker.onTick(levels(Skill.STRENGTH, 110, 99), CTX);
		assertTrue(tracker.onTick(levels(Skill.STRENGTH, 109, 99), CTX).isEmpty());
	}

	@Test
	public void removedRuleStopsEmitting()
	{
		BoostDecayTracker tracker = new BoostDecayTracker(Collections.singletonList(new HitpointsDecayRule()));
		tracker.onTick(levels(Skill.HITPOINTS, 99, 90), CTX);
		tracker.setRules(Collections.emptyList());
		assertTrue(tracker.onTick(levels(Skill.HITPOINTS, 98, 90), CTX).isEmpty());
	}
}

package com.boostdecay.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Skill;
import org.junit.Test;

public class HitpointsDecayRuleTest
{
	private static final StatSnapshot PREV = new StatSnapshot(99, 90);
	private static final StatSnapshot NOW = new StatSnapshot(98, 90);

	private final HitpointsDecayRule rule = new HitpointsDecayRule();

	@Test
	public void ruleIsForHitpoints()
	{
		assertEquals(Skill.HITPOINTS, rule.skill());
	}

	@Test
	public void decayWithoutHitsplat()
	{
		assertTrue(rule.isDecay(PREV, NOW, new TickContext(false, 0)));
	}

	@Test
	public void noDecayWithHitsplat()
	{
		assertFalse(rule.isDecay(PREV, NOW, new TickContext(true, 0)));
	}
}

package com.boostdecay.render;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class SplatLayoutTest
{
	@Test
	public void oneSplatIsCentered()
	{
		assertArrayEquals(new int[]{-12}, SplatLayout.xOffsets(new int[]{24}));
	}

	@Test
	public void twoSplatsAreCenteredWithGap()
	{
		// total 24 + 4 + 24 = 52
		assertArrayEquals(new int[]{-26, 2}, SplatLayout.xOffsets(new int[]{24, 24}));
	}

	@Test
	public void threeSplatsAreCenteredWithGaps()
	{
		// total 24*3 + 4*2 = 80
		assertArrayEquals(new int[]{-40, -12, 16}, SplatLayout.xOffsets(new int[]{24, 24, 24}));
	}

	@Test
	public void alphaIsFullForFirstTwoThirds()
	{
		assertEquals(1f, SplatLayout.alpha(0, 1200), 0f);
		assertEquals(1f, SplatLayout.alpha(800, 1200), 0f);
	}

	@Test
	public void alphaFadesLinearlyToZero()
	{
		assertEquals(0.5f, SplatLayout.alpha(1000, 1200), 0.001f);
		assertEquals(0f, SplatLayout.alpha(1200, 1200), 0f);
	}
